exports.shorthands = undefined;

// Global, collision-proof user system IDs — for EVERY account, one consistent
// scheme.
//
// Old scheme: per-school "TCH-000N" / "STU-000N" for students and teachers
// only (admins/parents/super-admins had none), generated by reading the max and
// adding one — which raced on the first row per school and broke past 9999
// (lexical sort). "TCH-0001" also existed in every school, so login-by-ID
// (which carries no school context) matched an arbitrary person.
//
// New scheme (shared/system-id.ts): <prefix><YY><seq>, e.g. T260001 / S260042.
//   prefix  S student · T staff · A school admin · P parent · X super admin
//   YY      last two digits of the year the account was created, frozen for life
//   seq     a per-(prefix, year) counter allocated across the WHOLE platform
//           via id_sequence — one atomic upsert per ID, no race, no read-max.
// The full ID is globally unique; system_id becomes NOT NULL with a single
// unique index, and login-by-ID is unambiguous.
//
// This migration REWRITES every existing system_id and BACKFILLS the accounts
// that never had one, ordered by created_at so the oldest account in each
// (prefix, year) keeps the lowest number.
// NOTE: anyone who logs in with their system ID must use the new value
// afterwards — communicate the change before running this against real users.

const PREFIX_CASE = `
  case u.role
    when 'student' then 'S'
    when 'teacher' then 'T'
    when 'parent' then 'P'
    when 'super_admin' then 'X'
    else 'A'                       -- school_admin, admin
  end`;

exports.up = (pgm) => {
  pgm.createTable("id_sequence", {
    scope: { type: "text", primaryKey: true },
    next_value: { type: "bigint", notNull: true },
  });

  // Assign every account a new ID and seed id_sequence from the highest number
  // issued per scope, in one statement. `ranked` reads the pre-statement
  // snapshot; `renamed` writes from it; the final INSERT reads the same
  // `ranked`.
  pgm.sql(`
    with ranked as (
      select
        u.id,
        (${PREFIX_CASE})                                              as p,
        to_char(u.created_at at time zone 'UTC', 'YYYY')              as yyyy,
        to_char(u.created_at at time zone 'UTC', 'YY')                as yy,
        row_number() over (
          partition by (${PREFIX_CASE}),
                       to_char(u.created_at at time zone 'UTC', 'YYYY')
          order by u.created_at, u.id
        )                                                             as seq
      from users u
    ),
    renamed as (
      update users u
         set system_id = r.p || r.yy || lpad(r.seq::text, 4, '0'),
             updated_at = now()
        from ranked r
       where u.id = r.id
      returning 1
    )
    insert into id_sequence (scope, next_value)
    select p || ':' || yyyy, max(seq)
      from ranked
     group by p, yyyy
  `);

  // Every account now has an ID in the new, globally-unique format — lock it in.
  pgm.alterColumn("users", "system_id", { notNull: true });
  pgm.sql(`drop index if exists users_school_id_system_id_unique_index`);
  pgm.sql(`create unique index users_system_id_unique on users (system_id)`);
};

exports.down = (pgm) => {
  pgm.sql(`drop index if exists users_system_id_unique`);
  pgm.alterColumn("users", "system_id", { notNull: false });
  pgm.sql(`
    create unique index users_school_id_system_id_unique_index
      on users (school_id, system_id)
      where system_id is not null
  `);
  pgm.dropTable("id_sequence");
  // The rewritten system_id values are not restored.
};
